    <div className="work-run-toolbar"><label>运行记录 <select aria-label="选择运行记录" value={runId || ''} onChange={event => go('tasks', task.projectId, { taskId, runId: event.target.value })}>{runs.map((item, index) => <option key={item.id} value={item.id}>运行 {index + 1} · {statusLabel(item.status)} · {date(item.createdAt)}</option>)}</select></label><div className="row gap-8">{['queued', 'running', 'waiting-dependencies'].includes(status) && <button className="button small" disabled={action.pending} onClick={() => void command('pause')}><Pause size={14}/>请求暂停</button>}{status === 'paused' && <button className="button small" disabled={action.pending} onClick={() => void command('resume')}><Play size={14}/>继续</button>}{['queued', 'running', 'paused', 'waiting-dependencies', 'waiting-user'].includes(status) && <button className="button small" disabled={action.pending} onClick={() => { if (window.confirm('取消后不再进入下一阶段；已提交请求仍可能返回并产生费用。确认请求取消？')) void command('cancel'); }}><Square size={13}/>请求取消</button>}{['failed', 'cancelled'].includes(status) && <button className="button small" disabled={action.pending} onClick={() => { if (window.confirm('建立新的运行记录重试，可能产生新的模型费用；历史成果保留。继续？')) void command('retry'); }}><RefreshCw size={14}/>重试为新运行</button>}<button className="button small" aria-expanded={conversation} onClick={() => setConversation(!conversation)}><MessageSquareText size={15}/>任务对话</button></div></div>
    {(run?.waitReason || run?.error) && <p className="work-error" role="status">{run.waitReason}{run.waitReason && run.error ? ' · ' : ''}{run.error}</p>}<ErrorNote error={action.error || detail.error || runDetail.error}/>
