    <div hidden={tab !== 'artifact'}>{artifacts.length > 0 ? <><label className="work-artifact-select">成果版本<select value={artifact ? `${artifact.id}:${artifact.version}` : ''} onChange={event => { setSelection({ runId: runId || '', key: event.target.value }); const item = artifacts.find(entry => `${entry.id}:${entry.version}` === event.target.value); if (item) go('tasks', task.projectId, { taskId, runId, artifactId: item.id, artifactVersion: String(item.version) }); }}>{artifacts.map(item => <option key={`${item.id}:${item.version}`} value={`${item.id}:${item.version}`}>{item.title} · V{item.version}{item.candidate ? ' · 候选' : ''}</option>)}</select></label>{artifact && artifacts.some(item => item.version > artifact.version) && <p className="info-box">有更新的成果版本。当前阅读和编辑保持不变，可从上方选择核对。</p>}{artifact && <ArtifactEditor key={`${artifact.id}:${artifact.version}`} artifact={artifact} projectId={task.projectId} headVersion={artifact.headVersion ?? artifact.version} onSaved={async next => { await detail.reload(); await runDetail.reload(); go('tasks', task.projectId, { taskId, runId: next.runId, artifactId: next.id, artifactVersion: String(next.version) }); }}/>}</> : <div className="work-empty"><FileText size={28}/><h3>尚无已保存成果</h3><p>任务成功须以后台保存的可读成果为准。你可以在活动中查看当前阶段和失败原因。</p></div>}</div>
    {tab === 'artifact' && artifact && !artifact.candidate && ['research', 'copy', 'script'].includes(artifact.kind) && task.role !== 'controller-planning' && <ExperienceCapture key={`${artifact.id}:${artifact.version}`} artifact={artifact}/>}
    {runId && <div hidden={tab !== 'activity'}><ActivityTimeline key={runId} taskId={taskId} runId={runId} visible={tab === 'activity'} initialEventId={target.eventId}/></div>}
