  function edit(nextTitle: string, nextBody: string) { setTitle(nextTitle); setBody(nextBody); setAck(false); saved.update({ artifactDrafts: { [draftKey]: { title: nextTitle, body: nextBody, baseVersion: originalHead.current } } }); }
  useEffect(() => { const warn = (event: BeforeUnloadEvent) => { if (dirty) { event.preventDefault(); event.returnValue = ''; } }; window.addEventListener('beforeunload', warn); return () => window.removeEventListener('beforeunload', warn); }, [dirty]);
  async function save() {
    const values = { title, body, expectedHeadVersion: originalHead.current };
    const fingerprint = JSON.stringify(values); if (request.current.fingerprint !== fingerprint) request.current = { fingerprint, id: workId() };
    await action.execute(async isCurrent => { await saved.save(); if (!isCurrent()) throw Error('工作区已切换，未继续保存成果'); return api<{ artifact: WorkArtifact }>(`/artifacts/${uri(artifact.id)}/versions/${artifact.version}`, 'PUT', { ...values, idempotencyKey: request.current.id }); }, async (result, isCurrent) => { saved.update({ artifactDrafts: { [draftKey]: null } }); await saved.save(); if (isCurrent()) await onSaved(result.artifact); });
  }
  return <article className="work-artifact"><div className="work-artifact-actions"><small>{artifact.kind} · V{artifact.version}{artifact.candidate ? ' · 候选成果（不会覆盖当前编辑）' : ''}</small><div className="row gap-8"><button className="button small" onClick={() => { download(new Blob([`# ${title}\n\n${body}\n`], { type: 'text/markdown;charset=utf-8' }), `${title.replace(/[\\/:*?"<>|]/g, '-').slice(0, 80) || '任务成果'}-v${artifact.version}.md`); }}><Download size={14}/>导出 Markdown</button><button className="button small" disabled={!saved.ready} onClick={() => setEditing(!editing)}>{editing ? '预览' : '编辑为新版本'}</button></div></div>{editing ? <><Field label="成果标题"><input value={title} maxLength={300} disabled={!saved.ready || action.pending} onChange={event => edit(event.target.value, body)}/></Field><Field label="成果正文"><textarea value={body} rows={18} maxLength={60000} disabled={!saved.ready || action.pending} onChange={event => edit(title, event.target.value)}/></Field>{headVersion !== originalHead.current && <p className="work-error">后台已有新版本。你的输入保留，保存时将检查冲突；请先复制或导出当前编辑。</p>}<label className="checkbox-row"><input type="checkbox" checked={ack} onChange={event => setAck(event.target.checked)}/><span>保留历史版本，并将此编辑保存为新的成果版本。</span></label><button className="button primary" disabled={!ack || !dirty || !title.trim() || action.pending || !saved.ready} onClick={() => void save()}><Save size={15}/>保存新版本</button><p className="small-note">输入自动保存为本任务的编辑草稿；保存新版本后才成为正式成果。</p></> : <><h2>{title}</h2><div className="work-artifact-text">{body || '此版本未包含正文。'}</div></>}{artifact.candidate && <div className="work-plan-diff"><p>这份成果尚未成为当前采用版本。确认后保存为新版本，下游任务才可使用。</p><button className="button" disabled={dirty || action.pending || !saved.ready} onClick={() => { if (window.confirm('采用此候选成果并允许依赖任务使用这一版本？已有版本会保留。')) void action.execute(() => api<{ artifact: WorkArtifact }>(`/artifacts/${uri(artifact.id)}/versions/${artifact.version}/adopt`, 'POST', { expectedHeadVersion: originalHead.current, idempotencyKey: workId() }), result => onSaved(result.artifact)); }}>明确采用候选成果</button></div>}<ErrorNote error={action.error || saved.error}/>{artifact.legacy?.assetId && <button className="button" disabled={dirty} onClick={() => go('studio', artifact.legacy?.projectId || projectId, { assetId: artifact.legacy?.assetId, tab: 'copy' })}>打开原成果编辑器 · 图片、校验与导出 <ArrowRight size={15}/></button>}<p className="small-note">这是已保存草稿，不代表已发布。手动编辑不会被随后到达的模型结果覆盖。</p></article>;
