type ExperienceSuggestion = { id: string; title: string; text: string };
type ExperienceSuggestions = { source: { projectId: string; taskId: string; runId: string; artifactId: string; artifactVersion: number; kind: string; accountId: string; title: string }; candidates: ExperienceSuggestion[]; allowedScopes: ('account' | 'project')[]; notice: string; manualAllowed?: boolean };
